#!/usr/bin/env bash
# benchmarks/queue/T_CRIU2_convergence_nommap.sh
# Generated by Antigravity for BENCH_07 (Host-Native like T_KV2)

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
source "${REPO_ROOT}/config/hardware.env"

# Tool Paths
CUDA_CHECKPOINT="/usr/local/bin/cuda-checkpoint"
CRIU="/usr/sbin/criu"
LLAMA_SERVER="${IK_LLAMA_BUILD_DIR}/bin/llama-server"

# Configuration
CKPT_DIR="${REPO_ROOT}/checkpoints/convergence_nommap"
rm -rf "${CKPT_DIR}" && mkdir -p "${CKPT_DIR}"
TIMESTAMP=$(date -u +%Y%m%dT%H%M%SZ)
RESULTS_DIR="${REPO_ROOT}/results/T_CRIU2_nommap_${TIMESTAMP}"
mkdir -p "${RESULTS_DIR}"

# Model path on host
MODEL_PATH="${MODEL_CACHE}/${CONVERGENCE_MODEL}"

PROMPT="List the three laws of thermodynamics in one sentence each."

echo "--- Step 0: Stopping any existing Convergence container ---"
CONV_CONTAINER=$(podman ps --format "{{.Names}}" | grep -i "convergence\|ikllamacpp" | head -1 || true)
if [ -n "${CONV_CONTAINER}" ]; then
    podman stop "${CONV_CONTAINER}" && podman rm "${CONV_CONTAINER}"
    sleep 3
fi

# --- Start llama-server on Host ---
echo "--- Step 1: Starting llama-server on Host (Cold Start) ---"
# Note: we use production-like flags but match BENCH_07 requirements
# LD_LIBRARY_PATH is needed for the ik_llama.cpp build
export LD_LIBRARY_PATH="${IK_LLAMA_BUILD_DIR}/src:${IK_LLAMA_BUILD_DIR}/ggml/src:${IK_LLAMA_BUILD_DIR}/examples/mtmd:/usr/local/cuda/targets/x86_64-linux/lib"

"${LLAMA_SERVER}" \
    --model "${MODEL_PATH}" \
    --port 8002 \
    --host 127.0.0.1 \
    -ngl 50 \
    --cpu-moe \
    --no-mmap \
    -t 32 -np 1 -c 4096 \
    --jinja > "${RESULTS_DIR}/llama_server.log" 2>&1 &

MAIN_PID=$!
echo "llama-server started with Host PID: ${MAIN_PID}"

# Wait for healthy
echo "Waiting for health check..."
for i in $(seq 1 120); do
    if curl -sf http://localhost:8002/health > /dev/null 2>&1; then
        echo "HEALTH OK"
        break
    fi
    if ! kill -0 $MAIN_PID 2>/dev/null; then
        echo "ERROR: llama-server died early. Check ${RESULTS_DIR}/llama_server.log"
        exit 1
    fi
    sleep 1
    [ $i -eq 120 ] && echo "TIMEOUT" && exit 1
done

# --- Warm inference ---
echo "Recording pre-checkpoint response..."
PRE_RESPONSE=$(curl -sf http://localhost:8002/v1/completions \
  -H "Content-Type: application/json" \
  -d "{\"model\":\"convergence\",\"prompt\":\"${PROMPT}\",\"max_tokens\":50,\"temperature\":0.0}")
echo "${PRE_RESPONSE}" > "${RESULTS_DIR}/pre_checkpoint_response.json"

# --- Checkpoint ---
echo "--- Step 2: Suspending GPU and Checkpointing (CRIU Dump) ---"
CKPT_START_MS=$(date +%s%3N)

echo "[T_CRIU2] Suspending GPU state for PID ${MAIN_PID}..."
sudo "${CUDA_CHECKPOINT}" --toggle --pid "${MAIN_PID}"

echo "[T_CRIU2] Performing CRIU Dump..."
if ! sudo "${CRIU}" dump \
    --tree "${MAIN_PID}" \
    --images-dir "${CKPT_DIR}" \
    --shell-job \
    --tcp-established \
    --file-locks; then
    echo "ERROR: CRIU Dump failed."
    sudo "${CUDA_CHECKPOINT}" --toggle --pid "${MAIN_PID}" || true
    exit 1
fi

CKPT_END_MS=$(date +%s%3N)
CKPT_ELAPSED_S=$(python3 -c "print(round(($CKPT_END_MS - $CKPT_START_MS) / 1000.0, 1))")
CKPT_SIZE_GB=$(sudo du -sh "${CKPT_DIR}" 2>/dev/null | awk '{print $1}')

echo "Checkpoint time: ${CKPT_ELAPSED_S}s"
echo "Checkpoint size: ${CKPT_SIZE_GB}"
echo "checkpoint_size_gb=${CKPT_SIZE_GB}" >> "${RESULTS_DIR}/timings.txt"
echo "checkpoint_elapsed_s=${CKPT_ELAPSED_S}" >> "${RESULTS_DIR}/timings.txt"

# Wait for process to disappear
sleep 2

# --- Restore ---
echo "--- Step 3: Restoring (CRIU Restore) ---"
RESTORE_START_MS=$(date +%s%3N)

echo "[T_CRIU2] Performing CRIU Restore..."
# restore-detached is used in T_KV2
sudo "${CRIU}" restore \
    --images-dir "${CKPT_DIR}" \
    --shell-job \
    --tcp-established \
    --file-locks \
    --restore-detached

# Resume GPU state
echo "[T_CRIU2] Resuming GPU state for PID ${MAIN_PID}..."
sudo "${CUDA_CHECKPOINT}" --toggle --pid "${MAIN_PID}"

RESTORE_END_MS=$(date +%s%3N)
RESTORE_ELAPSED_S=$(python3 -c "print(round(($RESTORE_END_MS - $RESTORE_START_MS) / 1000.0, 1))")

echo "Restore time: ${RESTORE_ELAPSED_S}s"
echo "restore_elapsed_s=${RESTORE_ELAPSED_S}" >> "${RESULTS_DIR}/timings.txt"

# Wait for health
echo "Waiting for health check after restore..."
for i in $(seq 1 120); do
  if curl -sf http://localhost:8002/health &>/dev/null; then
    echo "HEALTH OK"
    break
  fi
  sleep 1
done

# --- Post-restore inference ---
echo "--- Step 4: Post-Restore Verification ---"
POST_RESPONSE=$(curl -sf http://localhost:8002/v1/completions \
  -H "Content-Type: application/json" \
  -d "{\"model\":\"convergence\",\"prompt\":\"${PROMPT}\",\"max_tokens\":50,\"temperature\":0.0}")
echo "${POST_RESPONSE}" > "${RESULTS_DIR}/post_restore_response.json"

# Compare text
PRE_TEXT=$(python3 -c "import json; d=json.load(open('${RESULTS_DIR}/pre_checkpoint_response.json')); print(d['choices'][0]['text'])")
POST_TEXT=$(python3 -c "import json; d=json.load(open('${RESULTS_DIR}/post_restore_response.json')); print(d['choices'][0]['text'])")

if [ "${PRE_TEXT}" = "${POST_TEXT}" ]; then
  echo "TEXT_MATCH: Success"
  echo "text_match=identical" >> "${RESULTS_DIR}/timings.txt"
else
  echo "TEXT_MISMATCH: Outputs differ."
  echo "text_match=differs" >> "${RESULTS_DIR}/timings.txt"
fi

# --- Cleanup ---
echo "--- Step 5: Cleanup and Restoration of Production Container ---"
sudo kill -9 $MAIN_PID 2>/dev/null || true
"${REPO_ROOT}/infra/scripts/deploy.sh" ikllamacpp convergence ""

echo "RESTORE_OK" > "${RESULTS_DIR}/status.txt"
echo "Benchmark complete. Results in: ${RESULTS_DIR}"
